SELECT "Motos_1"."Marca" AS "Datos__copia_",   SUM("Motos_1"."InversionUS") AS "TEMP_TC___2622528870__0_",   SUM("Motos_1"."InversionUS") AS "sum_Calculation_0061002123102817_ok",   CAST(EXTRACT(YEAR FROM "Motos_1"."FECHA") AS BIGINT) AS "yr_FECHA_ok" FROM "Motos_1" WHERE ((CAST(EXTRACT(YEAR FROM "Motos_1"."FECHA") AS BIGINT) >= 2010) AND (CAST(EXTRACT(YEAR FROM "Motos_1"."FECHA") AS BIGINT) <= 2015) AND ("Motos_1"."Categoria" = 'MOTOCICLETAS')) GROUP BY "Motos_1"."Marca",   "yr_FECHA_ok";
